ACPI_STATUS AcpiPsCompleteScope(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *Next;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    /* Process the last operation in the parsing state */
    while (Op) {
        Next = Op->Common.Next;

        switch (Status) {
        case AE_CTRL_PENDING:
            /* Handle pending state */
            break;

        case AE_CTRL_TRANSFER:
            /* Handle control transfer */
            break;

        case AE_CTRL_TERMINATE:
            /* Terminate the operation and clear the scope */
            AcpiPsClearScope(WalkState);
            return (AE_OK);

        default:
            /* Handle any other status */
            break;
        }

        Op = Next;
    }

    /* Terminate the parsing state and clear the scope stack */
    AcpiPsClearScope(WalkState);

    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *NextOp;
    ACPI_PARSE_OBJECT *PrevOp;
    ACPI_STATUS Status2;

    if (WalkState->ScopeDepth > 0) {
        WalkState->ScopeDepth--;
    }

    while (Op) {
        if (Op->Common.Value.ArgList) {
            NextOp = Op->Common.Value.ArgList;
            Op->Common.Value.ArgList = NULL;
        }
        else {
            NextOp = Op->Common.Next;
        }

        if (Op->Common.Type & ACPI_PTYPE_CONTROL) {
            switch (Status) {
                case AE_CTRL_PENDING:
                    PrevOp = Op->Common.Parent;
                    if (PrevOp && (PrevOp->Common.Type & ACPI_PTYPE_CONTROL)) {
                        Status2 = AcpiPsCompleteOp(WalkState, PrevOp, AE_OK);
                        if (Status2 != AE_CTRL_PENDING) {
                            Status = Status2;
                        }
                    }
                    break;
                case AE_CTRL_TERMINATE:
                    break;
                default:
                    break;
            }
        }

        Op = NextOp;
    }

    if (WalkState->ScopeStack && (WalkState->ScopeDepth == 0)) {
        WalkState->ScopeStack = NULL;
    }

    return Status;
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_PARSE_OBJECT *Next;

    do {
        /* Complete the current operation */
        if (Op && Op->Common.Value.Arg) {
            AcpiUtRemoveReference(Op->Common.Value.Arg);
            Op->Common.Value.Arg = NULL;
        }

        /* Check if a callback is registered for the current op */
        if (WalkState->DescendingCallback) {
            Status = WalkState->DescendingCallback(WalkState, Op, WalkState->ClientData);
            if (ACPI_FAILURE(Status)) {
                return Status;
            }
        }

        /* Update the state of the walk */
        WalkState->CurrentOp = Op;
        if (Op) {
            Op = Op->Common.Next;
        }

        /* Handle any control flow */
        if (Status == AE_CTRL_PENDING) {
            Status = AE_OK;
        }
    } while (Status != AE_CTRL_TERMINATE);

    return Status;
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *Next;

    /* Complete the final operation and clear the scope stack */

    if (WalkState->ScopeInfo) {
        WalkState->ScopeInfo = WalkState->ScopeInfo->Prev;
    }

    if (WalkState->ControlState) {
        WalkState->ControlState = NULL;
    }

    while (Op) {
        Next = Op->Common.Next;

        if (Op->Common.Value.Arg) {
            AcpiUtDeleteInternalObjectDesc(Op->Common.Value.Arg);
        }

        if (Op->Common.Value.Node) {
            AcpiNsRemoveReference(Op->Common.Value.Node);
        }

        AcpiPsFreeOp(Op);

        Op = Next;
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteOp(
    ACPI_WALK_STATE       *WalkState,
    ACPI_PARSE_OBJECT     *Op,
    ACPI_STATUS           Status)
{
    ACPI_PARSE_OBJECT     *Parent;
    ACPI_PARSE_OBJECT     *Next;

    if (!WalkState || !Op)
    {
        return (AE_BAD_PARAMETER);
    }

    if (Status == AE_CTRL_PENDING)
    {
        WalkState->CtrlState = Op;
        return (AE_OK);
    }

    while (Op)
    {
        if (Op->Common.DisassembleHandle)
        {
            AcpiUtReleaseAcpiObject(Op->Common.DisassembleHandle);
            Op->Common.DisassembleHandle = NULL;
        }

        Parent = Op->Common.Parent;
        Next = Op->Common.Next;

        if (Parent)
        {
            if (Parent->Common.Value.Arg)
            {
                if (Parent->Common.Value.Arg->Common.Type == ACPI_PTYPE_NAMESTRING)
                {
                    ACPI_FREE(Parent->Common.Value.Arg->Common.Value.String);
                }
            }

            if (Parent->Common.Value.Arg == Op)
            {
                Parent->Common.Value.Arg = NULL;
            }
        }

        AcpiPsDeleteObject (Op);
        Op = Next;
    }

    if (Status != AE_OK && Status != AE_CTRL_TRANSFERRED)
    {
        AcpiUtWalkStack(WalkState->ParserState.Scope, NULL, NULL);
        WalkState->ParserState.Scope = NULL;
    }

    return (Status);
}
